window.ScripturaLexicons.BDAG_PART_0199 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-01\" data-source=\"BDAG\" data-search=\"κε´ numeral vinte e cinco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κε´</td><td>numeral</td><td>vinte e cinco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-02\" data-source=\"BDAG\" data-search=\"Κεγχρεαί, ῶν, αἱ topônimo Cencreia; porto de Corinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κεγχρεαί, ῶν, αἱ</td><td>topônimo</td><td>Cencreia; porto de Corinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-03\" data-source=\"BDAG\" data-search=\"κέδρος, ου, ἡ substantivo feminino cedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κέδρος, ου, ἡ</td><td>substantivo feminino</td><td>cedro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-04\" data-source=\"BDAG\" data-search=\"Κεδρών, ὁ topônimo Cedrom; vale a leste de Jerusalém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κεδρών, ὁ</td><td>topônimo</td><td>Cedrom; vale a leste de Jerusalém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-05\" data-source=\"BDAG\" data-search=\"κεῖμαι verbo jazer; estar situado; existir; ser destinado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεῖμαι</td><td>verbo</td><td>jazer; estar situado; existir; ser destinado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-06\" data-source=\"BDAG\" data-search=\"κειμήλιον, ου, τό substantivo neutro reserva; tesouro; investimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κειμήλιον, ου, τό</td><td>substantivo neutro</td><td>reserva; tesouro; investimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-07\" data-source=\"BDAG\" data-search=\"κειρία, ας, ἡ substantivo feminino atadura para sepultamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κειρία, ας, ἡ</td><td>substantivo feminino</td><td>atadura para sepultamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-08\" data-source=\"BDAG\" data-search=\"κείρω verbo tosquiar; cortar o cabelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κείρω</td><td>verbo</td><td>tosquiar; cortar o cabelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-09\" data-source=\"BDAG\" data-search=\"κέκμηκα remissão ver κάμνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κέκμηκα</td><td>remissão</td><td>ver κάμνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-10\" data-source=\"BDAG\" data-search=\"κέλευσις, εως, ἡ substantivo feminino ordem; diretriz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κέλευσις, εως, ἡ</td><td>substantivo feminino</td><td>ordem; diretriz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-11\" data-source=\"BDAG\" data-search=\"κέλευσμα, ατος, τό substantivo neutro sinal; voz de comando BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κέλευσμα, ατος, τό</td><td>substantivo neutro</td><td>sinal; voz de comando</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-12\" data-source=\"BDAG\" data-search=\"κελεύω verbo ordenar; mandar; solicitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κελεύω</td><td>verbo</td><td>ordenar; mandar; solicitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-13\" data-source=\"BDAG\" data-search=\"κενεμβατεύω forma conjectural dar um passo em falso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενεμβατεύω</td><td>forma conjectural</td><td>dar um passo em falso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-14\" data-source=\"BDAG\" data-search=\"κενοδοξέω verbo imaginar em vão; ter opinião inútil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενοδοξέω</td><td>verbo</td><td>imaginar em vão; ter opinião inútil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-15\" data-source=\"BDAG\" data-search=\"κενοδοξία, ας, ἡ substantivo feminino vaidade; presunção; ilusão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενοδοξία, ας, ἡ</td><td>substantivo feminino</td><td>vaidade; presunção; ilusão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-16\" data-source=\"BDAG\" data-search=\"κενόδοξος, ον adjetivo vaidoso; presunçoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενόδοξος, ον</td><td>adjetivo</td><td>vaidoso; presunçoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-17\" data-source=\"BDAG\" data-search=\"κενός, ή, όν adjetivo vazio; sem valor; em vão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενός, ή, όν</td><td>adjetivo</td><td>vazio; sem valor; em vão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-18\" data-source=\"BDAG\" data-search=\"κενόσπουδος, ον adjetivo ocupado com coisas sem valor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενόσπουδος, ον</td><td>adjetivo</td><td>ocupado com coisas sem valor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-19\" data-source=\"BDAG\" data-search=\"κενοφωνία, ας, ἡ substantivo feminino conversa vazia; tagarelice BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενοφωνία, ας, ἡ</td><td>substantivo feminino</td><td>conversa vazia; tagarelice</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0199-20\" data-source=\"BDAG\" data-search=\"κενόω verbo esvaziar; tornar sem efeito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κενόω</td><td>verbo</td><td>esvaziar; tornar sem efeito</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0199-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κε´</h1><div class=\"entry-meta\"><span>numeral</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κε</span>´ numeral: vinte e cinco, Hs 9, 4, 3; 9, 5, 4; 9, 15, 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κεγχρεαί, ῶν, αἱ</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κεγχρεαί</span>, <span class=\"greek\">ῶν</span>, <span class=\"greek\">αἱ</span> (Thu. [<span class=\"greek\">Κεγχρειαί</span>], X.+; edições também <span class=\"greek\">Κενχρ</span>-): Cencreia, porto marítimo de Corinto (Philo, In Flacc. 155: <span class=\"greek\">Κ</span>., <span class=\"greek\">τὸ</span> <span class=\"greek\">Κορίνθιον</span> <span class=\"greek\">ἐπίνειον</span>), no lado oriental do istmo (Strabo 8, 6, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:1</a>; subscrição. O porto no lado ocidental era Lequeu (Diod S 11, 16, 3 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Λεχαίου</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">Κεγχρεῶν</span>; 15, 68, 3).—WMichaelis, ZNW 25, 1926, 144–54; New Docs 3, 60 (moedas); 4, 139f; BHHW II 939; Kl. Pauly III, 182.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέδρος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κέδρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; LXX; TestSim 6:2; JosAs cap. 16 códice A [p. 64, 17 Bat.]; Philo, Aet. M. 64; Jos., Ant. 8, 44): cedro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:1</a>, variante de leitura (veja o verbete seguinte); 1 Cl 14:5 (Ps 36:35).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κεδρών, ὁ</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κεδρών</span>, <span class=\"greek\">ὁ</span> (também <span class=\"greek\">Κέδρων</span>, <span class=\"hebrew\">קִדְרוֹן</span>), indeclinável (Jos., Bell. 5, 70; 252 <span class=\"greek\">Κεδρών</span>, <span class=\"greek\">ῶνος</span>, Ant. 8, 17 <span class=\"greek\">τὸν</span> <span class=\"greek\">χειμάρρουν</span> <span class=\"greek\">Κεδρῶνα</span>): Cedrom; <span class=\"greek\">ὁ</span> <span class=\"greek\">χειμάρρους</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Κ</span>. (a LXX de Rahlfs não apresenta o artigo antes de <span class=\"greek\">Κ</span>. em nenhuma passagem; isso concorda com a boa tradição textual: 2 Km 15:23; 3 Km 2:37; 15:13; 4 Km 23:6, 12), o vale do Cedrom, uádi ou curso de água (seco exceto na estação chuvosa), contíguo a Jerusalém pelo leste e que deságua no mar Morto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:1</a> (variantes de leitura <span class=\"greek\">τοῦ</span> <span class=\"greek\">κέδρου</span>, <span class=\"greek\">τῶν</span> <span class=\"greek\">κεδρῶν</span>; veja <span class=\"greek\">κέδρος</span>).—GDalman, Jerusalem u. s. Gelände 1930, 182ff; BHHW II 946f; Kl. Pauly III 174. M-M. s.v. <span class=\"greek\">κέδρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεῖμαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεῖμαι</span> imperfeito, 3ª pessoa do singular <span class=\"greek\">ἔκειτο</span>; futuro, 3ª pessoa do plural <span class=\"greek\">κείσονται</span> (Tat. 31, 1) (Hom.+). ① Estar em posição reclinada, jazer, estar deitado, repousar; pode servir de passiva de <span class=\"greek\">τίθημι</span>; quanto a pessoas, com indicação de lugar, <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, em algum lugar: de uma criança, <span class=\"greek\">ἐν</span> <span class=\"greek\">φάτνῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:12</a>, 16; de um morto (Hom. e outros; também em inscrições sepulcrais palestinenses [PhilolWoch 49, 1929, 247] e alexandrinas [Sb 1397]; PRyl 114, 17 <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">κειμένου</span>), com <span class=\"greek\">οὗ</span> ou <span class=\"greek\">ὅπου</span> (ApcMos 33; PGM 4, 2038), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:12</a>. ② Estar em determinado lugar, de modo a encontrar-se sobre algo, jazer, a respeito de coisas, <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, sobre alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:15</a>. Também <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τινός</span> (TestAbr A 12 p. 91, 1 [Stone p. 30] <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πραπέζης</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:14</a> (<span class=\"greek\">κ</span>. relativo à localização de um lugar desde Hdt., Thu.; SIG 685, 46 [139 a.C.]; Tob 5:6 S <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄρει</span>; Jos., Ant. 9, 7).—Em uso absoluto (como Hom. e outros; Josh 4:6), a respeito de um trono ou banco, estar colocado, ficar (Hdt. 1, 181, 5 <span class=\"greek\">κλίνη</span> <span class=\"greek\">κ</span>.; Arrian, Anab. 6, 29, 6 <span class=\"greek\">τράπεζα</span> <span class=\"greek\">κ</span>.; Chariton 5, 4, 5; Polyaenus 4, 3, 24 e Paus. 2, 31, 3 <span class=\"greek\">θρόνος</span> <span class=\"greek\">κ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:2</a>; Hv 3, 1, 4. Sobre panos, estar ali, jazer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:12</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:5</a>, 6, 7.—21:9. De recipientes, estar colocados (X., Oec. 8, 19; Paus. 9, 31, 3 <span class=\"greek\">τρίποδες</span>; cf. 1 Esdr 6:25; Jer 24:1), 2:6; 19:29. <span class=\"greek\">σκάφην</span>, GJs 18:2 (códices). De bens, estar armazenados, guardados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:19</a> (Hom. e outros; cf. PSI 365, 20 [251/250 a.C.] <span class=\"greek\">ὁ</span> <span class=\"greek\">σῖτος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἅλω</span> <span class=\"greek\">κείμενος</span>).—Sobre um alicerce, estar lançado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:11</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">τετράγωνος</span> <span class=\"greek\">κεῖται</span>, a cidade está disposta em quadrado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span>, estar posto junto a algo, o machado junto às raízes (pronto para derrubar a árvore), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πρός</span> com acusativo também significa estar muito próximo de alguém em <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προφητικοῦ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κείμενος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτόν</span> (isto é, <span class=\"greek\">τ</span>. <span class=\"greek\">ἄνθρωπον</span>), Hm 11:9 (Ox 5 recto, 3 lê: <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῷ</span>). ③ Em diversos sentidos figurados que envolvem especialmente abstrações: existir, ter lugar, estar presente (para algo). ⓐ Ser designado, posto, destinado, <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, a alguma coisa; <span class=\"greek\">εἰς</span> <span class=\"greek\">πτῶσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνάστασιν</span>, para queda e levantamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:34</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπολογίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:16</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:3</a>.—<span class=\"greek\">κ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span>, ser encarregado de alguma coisa: do anjo da punição, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τιμωρίας</span>, responsável pela punição, Hs 6, 3, 2. ⓑ Estar estabelecido, existir, vigorar, sobre matérias jurídicas (termo técnico jurídico desde Eur.; Thu. e outros; veja também BGU 1002, 14 [55 a.C.] <span class=\"greek\">πᾶσαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">κείμεναι</span> <span class=\"greek\">συνγραφαί</span>; PTebt 334, 7, de contrato matrimonial <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κειμένην</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">συνγραφήν</span>; 2 Macc 4:11; <span class=\"greek\">κειμένου</span> <span class=\"greek\">νόμου</span>, Just., D. 123, 1), <span class=\"greek\">τινί</span>, para alguém; a respeito da lei (Menand., PDidot I, 14 p. 329 S. <span class=\"greek\">ἔστ</span>’ <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">κείμενος</span> <span class=\"greek\">νόμος</span>; Dio Chrys. 64 [14], 13; OGI 111, 30 [II a.C.] <span class=\"greek\">ὁ</span> <span class=\"greek\">κείμενος</span> <span class=\"greek\">νόμος</span>; papiros; EpArist 15; Philo, Det. Pot. Ins. 18 <span class=\"greek\">νόμος</span> <span class=\"greek\">κεῖται</span>; Jos., Ant. 4, 182 <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">κεῖται</span> = estão aí para vós), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:9</a>. De poderes, <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, existir para alguma coisa, relacionar-se ou aplicar-se a alguma coisa, Hm 6, 1, 1. ⓒ Ocorrer, aparecer, encontrar-se (Hellanicus [V a.C.] 4 Fgm. 93 Jac. <span class=\"greek\">αὕτη</span> [isto é, <span class=\"greek\">Πιτάνη</span>] <span class=\"greek\">παρ</span>’ <span class=\"greek\">Ἀλκαίῳ</span> <span class=\"greek\">κεῖται</span> = encontra-se em Alceu), <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span>, B 17:2. <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δούλου</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">κεῖται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παραβολῇ</span>;, por que o Filho de Deus aparece na parábola como escravo?, Hs 5, 5, 5; cf. 5, 6, 1. ⓓ Encontrar-se, estar, numa condição ou estado determinado (Hdt. 8, 102 e outros; Menand., Fgm. 576, 2 Kö. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρῳ</span> <span class=\"greek\">κειμένην</span> <span class=\"greek\">ἁμαρτίαν</span>; PTebt 27 I, 7 [113 a.C.] <span class=\"greek\">ἐν</span> <span class=\"greek\">περιστάσει</span> <span class=\"greek\">κειμένων</span>; 2 Macc 3:11; 4:31, 34; 3 Macc 5:26): <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πονηρῷ</span> <span class=\"greek\">κ</span>., o mundo jaz no (poder do) maligno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:19</a> (também é provável o significado <span class=\"greek\">κ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, depender de alguém [Soph., Oed. R. 247f; Polyb. 6, 15, 6]).—B. 834. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κειμήλιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κειμήλιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom. e outros; ApcEsdr 1:20 p. 25, 14 Tdf.; Philo, Joseph.): reserva, tesouro, investimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:19</a>, conjectura.—DELG s.v. <span class=\"greek\">κεῖμαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κειρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κειρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Aristoph.; Plut., Alcib. 16, 1: Alcibíades manda remover algumas tábuas do convés de sua embarcação para poder dormir suspenso sobre correias entrelaçadas, em vez de tábuas duras; Pr 7:16 faz referência semelhante a material para uma cama confortável; cf. <span class=\"greek\">κιρία</span>, PEdgar 69 [= Sb 6775], 9; PSI 341, 7; 387, 4. Sobre a grafia, B-D-F § 24; veja Mlt-H. 71f): referente ao preparo de cadáveres para sepultamento, material para ataduras (escólio sobre Aristoph., Av. 816 <span class=\"greek\">κειρία</span>· <span class=\"greek\">εἶδος</span> <span class=\"greek\">ζώνης</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">σχοινίων</span>, <span class=\"greek\">παρεοικὸς</span> <span class=\"greek\">ἱμάντι</span>, <span class=\"greek\">ᾗ</span> <span class=\"greek\">δεσμοῦσι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κλίνας</span> = ‘<span class=\"greek\">κειρία</span>: um tipo de cinto feito de cordas, algo semelhante às tiras usadas para formar o trançado de leitos’), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:44</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κείρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κείρω</span> futuro, 2ª pessoa do singular <span class=\"greek\">κερεῖς</span>, Pr 27:25; 1º aoristo <span class=\"greek\">ἔκειρα</span>; aoristo médio <span class=\"greek\">ἐκειράμην</span>. Na passiva: infinitivo de 2º aoristo <span class=\"greek\">καρῆναι</span> (TestJob 9:3); particípio perfeito <span class=\"greek\">κεκαρμένος</span>, LXX (Hom. e outros; inscrições, papiros, LXX; Jos., Bell. 6, 5; SibOr 3, 359): tosquiar uma ovelha (Artem. 4, 51 <span class=\"greek\">πρόβατον</span>; Babrius 51, 3; Jos., Ant. 6, 297, conforme 1 Km 25:2; TestJud 12:1): <span class=\"greek\">ὁ</span> <span class=\"greek\">κείρας</span> (variante de leitura <span class=\"greek\">ὁ</span> <span class=\"greek\">κείρων</span> [Aesop, Fab. 212 P.=382 H.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a>; 1 Cl 16:7; B 5:2 (os três segundo Is 53:7, onde aparecem ambas as leituras), o tosquiador. Na voz média, cortar o próprio cabelo ou mandar cortá-lo (B-D-F § 317; Rob. 809.—X., Hell. 1, 7, 8): <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>, mandar cortar o cabelo (em consequência de um voto; veja <span class=\"greek\">εὐχή</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:18</a>. Uso absoluto (Quint. Smyrn. 3, 686 e 688), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:6a</a>b.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκμηκα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">κέκμηκα</span> veja <span class=\"greek\">κάμνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλευσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κέλευσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κελεύω</span>; OGI 455, 3 [I a.C.]; Plut., Mor. 32c; frequente em inscrições e papiros a partir de [III d.C.]; também TestAbr A 16 p. 96, 23 [Stone p. 40]; Jos, Ant. 17, 65; Just., D. 42, 3; 102, 2): diretriz ou ordem. Acerca de um decreto imperial (veja <span class=\"greek\">δόγμα</span> 1b), GJs 17:1.—DELG s.v. <span class=\"greek\">κελεύω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλευσμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κέλευσμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κελεύω</span>; convocação para executar um procedimento, por exemplo, iniciar combate, remar ou caçar: Aeschyl., Hdt. e outros; Sb 4279, 3 [I d.C.]; Pr 30:27; TestSol 6:6 P; inscrição GrBar [<span class=\"greek\">κελεύματι</span>]; Philo, Abr. 116; Jos., Ant. 17, 140; 199; sobre a grafia, veja B-D-F § 70, 3): sinal, voz de comando (Hdt. 4, 141, sobre sinal para entrar em combate); <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καταβήσεται</span>, o Senhor descerá com voz de comando, isto é, quando for dada a ordem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:16</a> (cf., acerca do <span class=\"greek\">κέλευσμα</span> de Deus, Galen XIX 179 K. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δημιουργοῦ</span>; Philo, Praem. 117 e Descensus Mariae em Rtzst., Poim. 5, 3).—DELG s.v. <span class=\"greek\">κελεύω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κελεύω</span> (Hom.+), imperfeito <span class=\"greek\">ἐκέλευον</span>; futuro <span class=\"greek\">κελεύσω</span> (TestAbr B); 1º aoristo <span class=\"greek\">ἐκέλευσα</span>; mais-que-perfeito, 3ª pessoa do singular <span class=\"greek\">ἐκεκελεύκει</span> (Just., D. 103, 3). Na passiva: aoristo <span class=\"greek\">ἐκελεύσθην</span> (TestAbr A, Just.); particípio plural <span class=\"greek\">κελευσθέντες</span>, 4 Macc 9:11; perfeito passivo, 1ª pessoa do plural <span class=\"greek\">κεκελεύσμεθα</span> (Just., D. 48, 4): dar uma ordem, geralmente de caráter oficial, ordenar, mandar, instar, seguido de infinitivo aoristo (B-D-F § 338, 2; Rob. 857), que indica a ação a executar; a pessoa que recebe a ordem aparece no acusativo (SibOr 3, 298; com acusativo e <span class=\"greek\">ἵνα</span> TestAbr B 11 p. 116, 6 [Stone p. 80]); não ocorre em Mk, J, Paulo, B, IPol. <span class=\"greek\">κέλευσόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ἐλθεῖν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">σε</span>, ordena-me que vá até ti, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:28</a>; cf. versículo 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:15</a>; 22:30; 23:10; 24:8, variante de leitura; 1 Cl 43:2. Essa construção pode também ser entendida simplesmente como acusativo acompanhado de infinitivo, como evidentemente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:38</a>; MPol 16:1.—A construção em que <span class=\"greek\">κ</span>. é seguido de acusativo e infinitivo passivo, indicando que algo deve acontecer a alguém ou a alguma coisa sem identificar quem deverá executar a ordem, é mais conforme ao uso latino do que ao grego antigo (TestJob 5:3 <span class=\"greek\">ἀσφαλισθῆναι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θύρας</span>; veja B-D-F § 5, 3b; 392, 4; Rob. 111): <span class=\"greek\">ἐκέλευσεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">πραθῆναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:25</a>. Cf. 27:64; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:19</a>; 25:6, 17; especialmente Hs 9, 8, 5 (<span class=\"greek\">λίθους</span>) <span class=\"greek\">ἐκέλευσεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">τεθῆναι</span> e outras passagens; <span class=\"greek\">ἐκέλευσεν</span> <span class=\"greek\">αὐτῷ</span> (contra Paulo) <span class=\"greek\">ἀφεθῆναι</span> <span class=\"greek\">λέοντα</span>, AcPl Ha 4, 19; <span class=\"greek\">λυθῆναι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δεσμίους</span>, 11, 9.—Com infinitivo isolado, de modo que o restante deve ser suprido pelo contexto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:18</a>; 14:9; 27:58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:34</a>; 21:33; MPol 7:2.—O infinitivo presente ocorre mais raramente (B-D-F § 338, 2): com acusativo (X., An. 2, 1, 8; Chariton 7, 6, 2; TestJob 9:6; TestJos 13:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:34</a>; 22:24; 23:3, 35; 25:21; 27:43; 1 Cl 33:3; 40:1f; Hs 8, 1, 6f; 9, 3, 1 e 3f. Sem acusativo (X., Cyr. 2, 2, 2; Appian, Liby. 55 §241; Herodian 2, 3, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:22</a>; Dg 7:2.—Em uso absoluto, <span class=\"greek\">κελεύσαντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Φήστου</span>, por ordem de Festo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:23</a> (cf. Michel 594, 53 [279 a.C.] <span class=\"greek\">ἐπιμελητῶν</span> <span class=\"greek\">κελευόντων</span>; Jos., Ant. 11, 78 <span class=\"greek\">Δαρείου</span> <span class=\"greek\">κελεύσαντος</span>). <span class=\"greek\">θελήματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κελεύοντος</span> <span class=\"greek\">λόγου</span>, Dg 11:8.—Com dativo de pessoa e infinitivo (Longus 3, 8, 2; Polyaenus 3, 10, 11; Tob 8:18 BA; ApcMos 27:29 [aoristo].—Thu. 1, 44, 1; Diod S 19, 17, 3; Herm. Wr. 1, 29; 2 Macc 5:12; EpArist 184; TestJob 9:8; Jos., Ant. 20, 132 [presente]; com dativo e <span class=\"greek\">ἵνα</span> TestJob 39:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:35</a>, variante de leitura em lugar de <span class=\"greek\">παραγγείλας</span> (<span class=\"greek\">κ</span>. também se atenua para pedir insistentemente, convidar: Nicol. Dam.: 90 Fgm. 4 p. 332, 9ff Jac.; Epict., Fgm. 17, num convite; Arrian, Anab. 2, 6, 1, seus amigos fazem isso a Alexandre, o Grande; 3, 9, 3; 7, 2, 1; 7, 8, 3), AcPl Ha 4, 10.—Na passiva em construção pessoal (TestAbr B 7 p. 112, 12 [Stone p. 72]), <span class=\"greek\">καθὼς</span> <span class=\"greek\">ἐκελεύσθησαν</span>, Hs 9, 4, 1.—B. 1337. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενεμβατεύω</h1><div class=\"entry-meta\"><span>forma conjectural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενεμβατεύω</span> forma proposta exclusivamente por conjectura (W-H. e FHitzig; veja N. 25; cf. TAbbott [ICC] 269f) em lugar de <span class=\"greek\">ἐμβατεύω</span> (veja esse verbete), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>, dar um passo em falso. O verbo muito próximo <span class=\"greek\">κενεμβατέω</span>, ‘pisar no vazio, dar um passo em falso’, usado para andar na corda bamba, ocorre em Plut., Lucian e outros. Mlt-H. 273f; B-D-F § 154.—Cf. DELG s.v. <span class=\"greek\">κενός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοδοξέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενοδοξέω</span> sustentar uma opinião vã ou inútil, imaginar em vão (veja o verbete seguinte; Polyb. 12, 26c, 4; Dio Chrys. 21 [38], 29; 4 Macc 5:10; 8:24 <span class=\"greek\">κενοδοξήσωμεν</span>; Philo, Mut. Nom. 226; Tat. 12, 1), MPol 10:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοδοξία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενοδοξία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete seguinte). ① Avaliação vã ou exagerada de si mesmo, vaidade, presunção, ambição excessiva (Polyb. 3, 81, 9; Plut., Mor. 57d; Lucian, Dial. Mort. 20, 4; Vett. Val. 358, 31; 4 Macc 2:15; 8:19; AscIs 3, 26 e 28; Philo, De Jos. 36; Tat. 32, 1), <span class=\"greek\">κατὰ</span> <span class=\"greek\">κενοδοξίαν</span>, por vanglória vazia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:3</a>; IPhld 1:1. Em catálogo de vícios (como Cebes 24, 2), 1 Cl 35:5; Hm 8:5. ② Opinião vã ou sem valor, ilusão, engano, erro (desde Epicurus p. 78, 7 Us.; Wsd 14:14; Philo, Mut. Nom. 96, Leg. ad Gai. 114): <span class=\"greek\">ἐμπίπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄγκιστρα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., ser fisgado pelos anzóis do erro, IMg 11. <span class=\"greek\">φέρεσθαι</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τινός</span>, deixar-se desencaminhar pelas ilusões de alguém, Hs 8, 9, 3.—FWilhelm, RhM 70, 1915, 188; 72, 1917/18, 383f, com muitos exemplos.—M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόδοξος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενόδοξος</span>, <span class=\"greek\">ον</span> relativo a quem tem concepção exagerada de si mesmo, presunçoso, vaidoso, jactancioso (veja <span class=\"greek\">κενός</span>, <span class=\"greek\">δόξα</span>, Polyb. 27, 7, 12; 38, 7, 1; Epict. 3, 24, 43; M. Ant. 5, 1, 6; Vett. Val. 271, 2; PLond 1927, 33 [IV d.C.]; EpArist 8; Philo, Somn. 2, 105; advérbio <span class=\"greek\">κενοδόξως</span>, Tat. 12, 3), D 3:5. <span class=\"greek\">μὴ</span> <span class=\"greek\">γινώμεθα</span> <span class=\"greek\">κενόδοξοι</span>, não nos tornemos presunçosos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:26</a>.—DELG s.v. <span class=\"greek\">κενός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Hom.+), geralmente ‘vazio’. ① Que não contém algo material, vazio (TestJob 10:4; GrBar 12:6; Jos., Vi. 167): <span class=\"greek\">κεράμιον</span>, jarro vazio, Hm 11:15; <span class=\"greek\">σκεῦος</span> (4 Km 4:3), m 11:13. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀποστέλλειν</span> <span class=\"greek\">τινά</span>, despedir alguém de mãos vazias (cf. PRein 55, 9 [III d.C.] <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀναπέμψῃς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κενόν</span>; Gen 31:42; Dt 15:13; Job 22:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:53</a>; 20:10f. ② Desprovido de valor intelectual, moral ou espiritual, vazio, extensão figurada da acepção 1. ⓐ Quanto a coisas, sem conteúdo, sem fundamento, sem verdade, sem poder: <span class=\"greek\">κ</span>. <span class=\"greek\">λόγοι</span>, palavras vazias (Pla., Laches 196b; Menand., Mon. 512 [752 J.] Mei.; Herm. Wr. 16, 2; Ex 5:9; Dt 32:47; Jos., C. Ap. 2, 225; TestNapht 3:1.—PParis 15, 68 [120 a.C.] <span class=\"greek\">φάσει</span> <span class=\"greek\">κενῇ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:18</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:6</a>; Dg 8:2; AcPl Ox 6, 13 (cf. Aa I 241, 14); cf. D 2:5. <span class=\"greek\">πνεῦμα</span>, Hm 11:11, 17. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπάτη</span>, engano vazio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a> (cf. Arrian, Anab. 5, 10, 4 <span class=\"greek\">κενὸς</span> <span class=\"greek\">φόβος</span> = alarme falso). Das coisas da vida cotidiana, vãs, Hm 5, 2, 2; <span class=\"greek\">τρυφή</span>, 12, 2, 1; <span class=\"greek\">πεποίθησις</span>, Hs 9, 22, 3. Sobre pregação e fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:14a</a>b (cf. o tema de ‘esperança vazia’, Reader, Polemo p. 313); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:20</a> P 74 (cf. Demosth. 18, 150 <span class=\"greek\">κ</span>. <span class=\"greek\">πρόφασις</span>; Aeschyl., Pers. 804 <span class=\"greek\">κ</span>. <span class=\"greek\">ἐλπίς</span>; cf. Wsd 3:11; Sir 34:1). Como <span class=\"greek\">κ</span>. = <span class=\"greek\">μάταιος</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:17</a>), as duas palavras se encontram juntas no mesmo sentido (cf. Demosth. 2, 12; Plut., Artox. 1018 [15, 6], Mor. 1117a; Oenomaus em Eus., PE 5, 21, 5 <span class=\"greek\">κενὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μάταια</span> acerca de oráculos; Hos 12:2; Job 20:18; EpArist 205), 1 Cl 7:2; cf. <span class=\"greek\">κενὴ</span> <span class=\"greek\">ματαιολογία</span>, Pol 2:1. ⓑ Quanto a pessoas (Pind. e outros; Soph., Ant. 709; Plut., Mor. 541a <span class=\"greek\">ἀνόητοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κενοί</span>; Epict. 2, 19, 8; 4, 4, 35; Judg 9:4; 11:3 B; Philo, Spec. Leg. 1, 311; Just., D. 64, 2 <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">κενοί</span>): tolo, sem discernimento, vazio, Hm 12, 4, 5; <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">κενοί</span>, 11:15; <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:20</a>; Pol 6:3; <span class=\"greek\">τῶν</span> <span class=\"greek\">δούλων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κ</span>., Hs 6, 2, 1; <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">κενὸς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δικαίου</span>, vazio do espírito justo, Hm 5, 2, 7; <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, 11:4; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">κ</span>., Hs 9, 19, 2 (cf. <span class=\"greek\">κενοὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀγάπης</span>, Iren. 4, 33, 7 [Harv. II 261, 2]). Em paronomásia (cf. Job 27:12), <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὢν</span> <span class=\"greek\">κενὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποκρίνεται</span> <span class=\"greek\">κενοῖς</span>, ele próprio, vazio (do Espírito de Deus), dá respostas vazias a pessoas vazias, m 11:3.—Versículo 13. ③ Desprovido de propósito ou resultado, em vão: <span class=\"greek\">κενὰ</span> <span class=\"greek\">μελετᾶν</span>, imaginar coisas vãs, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:25</a> (Ps 2:1); <span class=\"greek\">κενὸν</span> <span class=\"greek\">γενέσθαι</span>, ser em vão: <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κενὴ</span> <span class=\"greek\">ἐγενήθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:10</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">εἴσοδος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">γέγονεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:1</a>; <span class=\"greek\">κόπος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.58\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:58</a>.—<span class=\"greek\">εἰς</span> <span class=\"greek\">κενόν</span>, em vão, sem propósito (Diod S 19, 9, 5; Heliod. 10, 30; PPetr II, 37, 1b recto, 12 [III a.C.]; Kaibel 646, 10; Lev 26:20; Is 29:8; 65:23; Jer 6:29; TestJob 24:2 [<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. nos códices, S. e V. com Job 2:9f]; Jos., Ant. 19, 27; 96), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:1</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τρέχειν</span>, correr em vão (cf. Menand., Mon. 51 Mei. <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">ἄβουλος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μοχθεῖ</span> <span class=\"greek\">τρέχων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:16a</a>, reproduzido em Pol 9:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:16b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a>.—B. 932. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόσπουδος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενόσπουδος</span>, <span class=\"greek\">ον</span> que se ocupa com coisas sem valor (Plut., Mor. 560b; 1061c; 1069b; Diog. L. 9, 68), <span class=\"greek\">ἐὰν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μὴ</span> <span class=\"greek\">εὑρεθῇς</span>, se não se verificar que te ocupas com coisas sem valor, Hs 9, 5, 5.—DELG s.v. <span class=\"greek\">κενός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοφωνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενοφωνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κενός</span>, <span class=\"greek\">φωνέω</span>; Diosc., Mat. Med. Praef. 2 W.; Porphyr., Adv. Christ. 58, 15 Harnack; Hesychius e Suda = <span class=\"greek\">ματαιολογία</span>): fala que não tem valor, tagarelice, conversa vazia; <span class=\"greek\">βέβηλοι</span> <span class=\"greek\">κενοφωνίαι</span>, conversas profanas e vazias, isto é, destituídas de conteúdo cristão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:16</a> (como variante de leitura em ambas as passagens, <span class=\"greek\">καινοφωνίαι</span>, jargão contemporâneo, a menos que isso seja apenas uma variante fonética ou itacismo, pois naquele período <span class=\"greek\">αι</span> era pronunciado como <span class=\"greek\">ε</span>).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0199-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κενόω</span> futuro <span class=\"greek\">κενώσω</span>; 1º aoristo <span class=\"greek\">ἐκένωσα</span>. Na passiva: aoristo <span class=\"greek\">ἐκενώθην</span>; perfeito passivo <span class=\"greek\">κεκένωμαι</span> (veja <span class=\"greek\">κενός</span>; Trag., Hdt. e outros; papiros; Jer 14:2; 15:9; Philo; Jos., Ant. 8, 258, variante de leitura). ① Tornar vazio, esvaziar. ⓐ Quanto ao abandono por um espírito terreno, na passiva <span class=\"greek\">κενοῦται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span>, o homem é esvaziado, Hm 11:14. ⓑ Quanto à renúncia de posição ou prestígio: de Cristo, que renunciou à aparência de sua divindade e assumiu a forma de servo, <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐκένωσεν</span>, esvaziou-se a si mesmo, despojou-se de seu prestígio ou privilégios, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:7</a> (veja <span class=\"greek\">ἁρπαγμός</span> 2 e JRoss, JTS 10, 1909, 573f, apoiado por WWarren, On <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐκένωσεν</span>: JTS 12, 1911, 461–63; KPetersen, <span class=\"greek\">ἑαυτ</span>. <span class=\"greek\">ἐκέν</span>.: SymbOsl 12, ’33, 96–101; WWilson, ET 56, ’45, 280; ELewis, Interpretation 1, ’47, 20–32; ESchweizer, Erniedrigung u. Erhöhung bei Jesus u. seinen Nachfolgern ’62; HRobinson, The Cross in the OT ’55, 103–5; RMartin, An Early Christian Confession ’60; JJeremias, TW V 708, sustenta que a kénosis não é a encarnação, mas a cruz [Is 53:12], e defende sua posição, NovT 6, ’63, 182–88; DGeorgi, Der Vorpaulinische Hymnus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:6</a>–11 em Bultmann Festschr., ’64, 263–93; JHarvey, ET 76, ’65, 337–39 [tipologia de Adão]; a perspectiva contracultural neste versículo contrasta com a opinião de Etéocles em Eur., Phoen. 504–9).—Cf. <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">ἐκενώθησαν</span>, muitos foram transformados em insensatos, Hs 9, 22, 3. ② Tornar algo sem resultado ou efeito, destruir, anular, tornar ineficaz (Vett. Val. 90, 7): <span class=\"greek\">τὸ</span> <span class=\"greek\">καύχημά</span> <span class=\"greek\">μου</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">κενώσει</span>, ninguém me privará de meu motivo de orgulho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:15</a>. Na passiva: <span class=\"greek\">κεκένωται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span>, a fé é tornada sem efeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:14</a>; <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κενωθῇ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σταυρὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:17</a>; <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καύχημα</span> <span class=\"greek\">ἡμῶν</span> … <span class=\"greek\">κενωθῇ</span>, para que a nossa vanglória a vosso respeito não se revele vazia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:3</a> (cf. <span class=\"greek\">καύχημα</span> 2).—DELG s.v. <span class=\"greek\">κενός</span>. M-M. EDNT. TW. Spicq.</p></section></article>"};
